def add_cam(name, sensor_w, sensor_h, lens, res_x, res_y):
    cd = bpy.data.cameras.new(name); cd.sensor_fit = "HORIZONTAL"; cd.sensor_width = sensor_w; cd.sensor_height = sensor_h; cd.lens = lens
    o = bpy.data.objects.new(name, cd); o.rotation_mode = "QUATERNION"; c_cam.objects.link(o); return o
def key_cam(o, f, loc, q):
    o.location = loc; o.rotation_quaternion = q
    o.keyframe_insert("location", frame=f); o.keyframe_insert("rotation_quaternion", frame=f)
